def b91decode(data):
    """Decode Base91 string to bytes."""
    b = 0
    n = 0
    out = []
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"'

    for c in data:
        if c not in alphabet:
            continue
        v = alphabet.index(c)
        if v < 0 or v > 90:
            continue
        if n == 0:
            b = v
            n = 13
        else:
            b += v * (1 << n)
            n += 13 if (b & 8191) > 88 else 14
            while True:
                out.append(bytes([b & 255]))
                b >>= 8
                n -= 8
                if n <= 7:
                    break

    if n > 0:
        out.append(bytes([b]))

    return b''.join(out).decode('latin1')

def num_times_all_blue(light):
    max_bulb = 0
    count = 0
    for i, bulb in enumerate(light):
        max_bulb = max(max_bulb, bulb)
        if max_bulb == i + 1:
            count += 1
    return count

def unhappyFriends(n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
    # Create pairing dictionary
    pair = {}
    for x, y in pairs:
        pair[x] = y
        pair[y] = x

    # Create preference ranking dictionaries for quick lookup
    pref_rank = [{} for _ in range(n)]
    for i in range(n):
        for rank, friend in enumerate(preferences[i]):
            pref_rank[i][friend] = rank

    unhappy = set()

    # Check each friend for unhappiness
    for x in range(n):
        y = pair[x]
        for u in preferences[x]:
            if u == y:
                break  # No more preferred friends
            v = pair[u]
            if pref_rank[u][x] < pref_rank[u][v]:
                unhappy.add(x)
                break

    return len(unhappy)

from typing import List

class Solution:
    def minSwaps(self, grid: List[List[int]]) -> int:
        n = len(grid)
        # For each row, count trailing zeros (from the end)
        trailing_zeros = []
        for row in grid:
            zeros = 0
            for i in range(n - 1, -1, -1):
                if row[i] == 0:
                    zeros += 1
                else:
                    break
            trailing_zeros.append(zeros)

        swaps = 0
        # Iterate to find the required trailing zeros for each row
        for i in range(n):
            required_zeros = n - 1 - i
            # Find the first row with >= required_zeros and swap it up
            found = -1
            for j in range(i, n):
                if trailing_zeros[j] >= required_zeros:
                    found = j
                    break
            if found == -1:
                return -1
            # Swap rows to bring found row to position i
            # Record the swap steps (j - i for adjacent swaps)
            swaps += found - i
            # Update trailing_zeros list (move the found row to position i)
            row_zeros = trailing_zeros.pop(found)
            trailing_zeros.insert(i, row_zeros)
        return swaps
